import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  experimental: {
    after: true
  }
};

export default nextConfig;

"use server";

interface PageViewData {
  path: string;
  timestamp: number;
  userAgent?: string;
}

export async function logPageView(data: PageViewData) {
  // Simulating analytics service call
  // In production, replace this with your actual analytics provider (e.g., Google Analytics, Segment, Mixpanel)
  await new Promise((resolve) => setTimeout(resolve, 100));

  console.log(`[Analytics] Page view logged:`, {
    path: data.path,
    timestamp: new Date(data.timestamp).toISOString(),
    userAgent: data.userAgent || "unknown"
  });

  // Example: Send to analytics service
  // await fetch('https://analytics.example.com/track', {
  //   method: 'POST',
  //   headers: { 'Content-Type': 'application/json' },
  //   body: JSON.stringify(data)
  // });
}

import { unstable_after } from "next/server";
import { headers } from "next/headers";
import { logPageView } from "../lib/analytics";

export default async function WelcomeServer() {
  // Get request headers for analytics
  const headersList = await headers();
  const userAgent = headersList.get("user-agent") || undefined;

  // Schedule analytics logging AFTER the response is sent
  // This ensures the response isn't delayed by the analytics call
  unstable_after(async () => {
    await logPageView({
      path: "/",
      timestamp: Date.now(),
      userAgent
    });
  });

  return (
    <main>
      <h1>Welcome!</h1>
      <p>This is a server component that logs page views asynchronously.</p>
      <p>The analytics logging happens after the response is sent, so it never blocks the page load.</p>
    </main>
  );
}

